set -eu
python3 - <<'PY'
data={'site': 'eu', 'links': [{'peer': 'us', 'interface': 'wgeuus', 'local': '172.31.0.1', 'remote': '172.31.0.2', 'port': 51821}, {'peer': 'jp', 'interface': 'wgeujp', 'local': '172.31.0.5', 'remote': '172.31.0.6', 'port': 51822}, {'peer': 'cn', 'interface': 'wgeucn', 'local': '172.31.0.9', 'remote': '172.31.0.10', 'port': 51823}], 'dc': ['10.110.0.0/24', '10.120.0.0/24', '10.130.0.0/24', '10.140.0.0/24']}

import subprocess,json,re,time,zlib,base64
D=data
commands=[]
def run(args,timeout=10):
 p=subprocess.run(args,capture_output=True,text=True,timeout=timeout);commands.append({'command':args,'exit':p.returncode});return p.stdout.strip() if p.returncode==0 else ('ERROR '+p.stderr.strip())
raw=run(['birdc','show','protocols','all']);blocks=re.split(r'(?m)(?=^(?:mesh_|azure_)\S+\s+BGP\s)',raw);protocols={};selected=[]
for b in blocks:
 lines=b.splitlines()
 if not lines or not re.match(r'^(mesh_|azure_)\S+\s+BGP\s',lines[0]):continue
 row=lines[0];cols=row.split();state=re.search(r'BGP state:\s*(\S+)',b);err=re.search(r'Last error:\s*(.*)',b)
 protocols[cols[0]]={'row':row,'protocolState':cols[3],'info':' '.join(cols[5:]),'bgpState':state.group(1) if state else None,'lastError':err.group(1) if err else None}
 selected.extend([row]+[x for x in lines[1:] if re.search(r'BGP state:|Last error:',x)])
routes=[]
for link in D['links']:
 args=['ip','route','get',link['remote'],'from',link['local']];text=run(args);routes.append(dict(peer=link['peer'],source=link['local'],destination=link['remote'],expectedInterface=link['interface'],raw=text,correctDevice=('dev '+link['interface']) in text))
exports={}
for name in protocols:
 if name.startswith('azure_'):
  text=run(['birdc','show','route','export',name]);prefixes=re.findall(r'(?m)^\s*(10\.\d+\.\d+\.\d+/\d+)',text)
  exports[name]={'prefixes':prefixes,'allFourDc':all(p in prefixes for p in D['dc']),'raw':text}
wg={}
for link in D['links']:
 iface=link['interface'];h=run(['wg','show',iface,'latest-handshakes']).split();endpoint=run(['wg','show',iface,'endpoints']).split();wg[iface]={'handshakeAgeSeconds':int(time.time())-int(h[1]) if len(h)>1 else None,'endpoint':endpoint[1] if len(endpoint)>1 else None,'fwmark':run(['wg','show',iface,'fwmark']),'listenPort':run(['wg','show',iface,'listen-port'])}
nat=run(['iptables-save','-t','nat']);rules=run(['ip','rule','show']);t220=run(['ip','route','show','table','220']);main=run(['ip','route','show','table','main']);lab=run(['birdc','show','route','table','lab4'])
ike=run(['swanctl','--list-sas']) if D['site']=='jp' else '';ikeproof=[x for x in ike.splitlines() if re.search(r'ESTABLISHED|INSTALLED|IKEv2',x)]
capture=None
if all(r['correctDevice'] for r in routes) and any(p['bgpState']!='Established' for n,p in protocols.items() if n.startswith('mesh_')):
 capture=run(['timeout','8','tcpdump','-nn','-i','any','-c','12','tcp port 179 and net 172.31.0.0/24'],timeout=10)
result={'site':D['site'],'observedAtUnix':int(time.time()),'protocols':protocols,'protocolsAllRelevantRaw':selected[:20],'innerRoutes':routes,'rulesRaw':rules,'table220Raw':t220,'mainRoutesRaw':main,'labRoutesRaw':lab,'azureExports':exports,'wireguard':wg,'natRaw':nat,'wireguardNatPresent':'TH_WG_' in nat,'ike2SaProof':ikeproof,'tcpdumpIfNeeded':capture,'commands':commands}
print('MESHVERIFY '+base64.b64encode(zlib.compress(json.dumps(result,separators=(',',':')).encode(),9)).decode())

